# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-24
# Pester tests: the spool config object and the free-space check before a service
# (need = last archive size x headroomRatio + headroomGiB).

BeforeAll {
    . (Join-Path $PSScriptRoot '../TestHelpers.ps1')

    function New-Cfg {
        # a config with one service 'app'; -Root / -Svc are the JSON of the spool objects
        param([string]$Root = '', [string]$Svc = '')
        $rootPart = if ($Root) { """spool"": $Root," } else { '' }
        $svcPart = if ($Svc) { """spool"": $Svc," } else { '' }
        return @"
{ "window": { "open": "00:00", "close": "23:59" }, $rootPart
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1", $svcPart
    "steps": [ { "name": "dump", "resources": [] } ] } } }
"@ | ConvertFrom-Json
    }
}

AfterAll {
    Remove-TestWork
}

Describe 'spool headroom settings' {
    It 'defaults to 1.2 and 10 GiB' {
        $h = Get-SpoolHeadroom -Config (New-Cfg) -Service 'app'
        $h.Ratio | Should -Be 1.2
        $h.MarginBytes | Should -Be (10 * 1GB)
    }

    It 'takes the top-level values' {
        $h = Get-SpoolHeadroom -Config (New-Cfg -Root '{ "headroomRatio": 1.5, "headroomGiB": 0 }') -Service 'app'
        $h.Ratio | Should -Be 1.5
        $h.MarginBytes | Should -Be 0
    }

    It 'lets a service override one key and keep the other from the top level' {
        $h = Get-SpoolHeadroom -Config (New-Cfg -Root '{ "headroomRatio": 1.5, "headroomGiB": 4 }' -Svc '{ "headroomRatio": 1.1 }') -Service 'app'
        $h.Ratio | Should -Be 1.1
        $h.MarginBytes | Should -Be (4 * 1GB)
    }

    It 'accepts a fractional GiB margin and a ratio under 1' {
        $h = Get-SpoolHeadroom -Config (New-Cfg -Svc '{ "headroomRatio": 0.8, "headroomGiB": 0.5 }') -Service 'app'
        $h.Ratio | Should -Be 0.8
        $h.MarginBytes | Should -Be (512 * 1MB)
    }
}

Describe 'spool path' {
    It 'reads spool.path' {
        Get-SpoolRoot -Config (New-Cfg -Root '{ "path": "/data/spool" }') -Default '/def' | Should -Be '/data/spool'
    }

    It 'falls back to the default when the path is missing or empty' {
        Get-SpoolRoot -Config (New-Cfg) -Default '/def' | Should -Be '/def'
        Get-SpoolRoot -Config (New-Cfg -Root '{ "headroomRatio": 1.1 }') -Default '/def' | Should -Be '/def'
        Get-SpoolRoot -Config (New-Cfg -Root '{ "path": "" }') -Default '/def' | Should -Be '/def'
    }
}

Describe 'spool config problems' {
    It 'accepts a missing spool and a valid object' {
        @(Get-SpoolConfigProblems -Config (New-Cfg)).Count | Should -Be 0
        @(Get-SpoolConfigProblems -Config (New-Cfg -Root '{ "path": "/s", "headroomRatio": 1.2, "headroomGiB": 10 }')).Count | Should -Be 0
        @(Get-SpoolConfigProblems -Config (New-Cfg -Svc '{ "headroomRatio": 1.1 }') -Service 'app').Count | Should -Be 0
    }

    It 'refuses the plain path form, quoting the object to write instead' {
        $p = @(Get-SpoolConfigProblems -Config (New-Cfg -Root '"/data/spool"'))
        $p.Count | Should -Be 1
        $p[0] | Should -Match 'no longer read'
        $p[0] | Should -Match ([regex]::Escape('"spool": { "path": "/data/spool" }'))
    }

    It 'refuses a path in a service spool' {
        $p = @(Get-SpoolConfigProblems -Config (New-Cfg -Svc '{ "path": "/other" }') -Service 'app')
        $p -join "`n" | Should -Match 'spool.path: one spool per sequencer'
    }

    It 'refuses a service spool that is not an object' {
        @(Get-SpoolConfigProblems -Config (New-Cfg -Svc '1.1') -Service 'app') -join "`n" | Should -Match 'must be an object'
    }

    It 'flags bad values: <Json>' -ForEach @(
        @{ Json = '{ "headroomRatio": 0 }'; Expect = 'headroomRatio: must be a number above 0' }
        @{ Json = '{ "headroomRatio": -1 }'; Expect = 'headroomRatio: must be a number above 0' }
        @{ Json = '{ "headroomRatio": "1.2" }'; Expect = 'headroomRatio: must be a number above 0' }
        @{ Json = '{ "headroomGiB": -1 }'; Expect = 'headroomGiB: must be a number, 0 or more' }
        @{ Json = '{ "headroomGiB": "10" }'; Expect = 'headroomGiB: must be a number, 0 or more' }
        @{ Json = '{ "headroomGB": 10 }'; Expect = "unknown key 'headroomGB'" }
        @{ Json = '{ "path": 3 }'; Expect = 'spool.path: must be a string' }
    ) {
        @(Get-SpoolConfigProblems -Config (New-Cfg -Root $Json)) -join "`n" | Should -Match ([regex]::Escape($Expect))
    }

    It 'shows a bad service spool in the service validation' {
        $ev = Join-Path $Work 'sh-val.jsonl'
        $problems = @(Get-ServiceValidationProblems -Config (New-Cfg -Svc '{ "headroomRatio": 0 }') -Service 'app' -BaseDir $TestsDir -EventsPath $ev)
        $problems -join "`n" | Should -Match 'headroomRatio'
    }
}

Describe 'free-space check before a service' {
    BeforeEach {
        $t = New-SpoolTestEnv -Prefix 'sh'
        $script:ev = $t.Ev; $script:root = $t.Root; $script:paths = $t.Paths
    }

    It 'skips when free < last x ratio + margin, with the formula in the line and the event' {
        # last archive 10 GiB, defaults -> need 10 x 1.2 + 10 = 22 GiB
        Add-Content -LiteralPath $ev -Value (@{ ts = (Get-Date).AddDays(-2).ToString('o'); type = 'service.end'; svc = 'app'; status = 'ok'; bytes = 10GB } | ConvertTo-Json -Compress)
        Mock -ModuleName BackupCommon Get-FreeSpaceBytes { 22GB - 1 }
        $lines = Get-RunLines -Config (New-Cfg) -Paths $paths
        ($lines -join "`n") | Should -Match ([regex]::Escape('insufficient space in the spool (need 22.0 GB = 10.0 GB x 1.2 + 10.0 GB, free 22.0 GB)'))
        $skip = @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.skip' -and $_.svc -eq 'app' })
        $skip.Count | Should -Be 1
        $skip[0].reason | Should -Be 'insufficient-space'
        [long]$skip[0].needBytes | Should -Be (22GB)
        [long]$skip[0].lastBytes | Should -Be (10GB)
        [double]$skip[0].ratio | Should -Be 1.2
        [long]$skip[0].marginBytes | Should -Be (10GB)
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeFalse
    }

    It 'runs when free equals the need' {
        Add-Content -LiteralPath $ev -Value (@{ ts = (Get-Date).AddDays(-2).ToString('o'); type = 'service.end'; svc = 'app'; status = 'ok'; bytes = 10GB } | ConvertTo-Json -Compress)
        Mock -ModuleName BackupCommon Get-FreeSpaceBytes { 22GB }
        Get-RunLines -Config (New-Cfg) -Paths $paths | Out-Null
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.skip' }).Count | Should -Be 0
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeTrue
    }

    It 'uses the service override (a lower ratio lets the big service run)' {
        # need 10 x 1.2 + 10 = 22 GiB by default; with ratio 1.0 and no margin: 10 GiB
        Add-Content -LiteralPath $ev -Value (@{ ts = (Get-Date).AddDays(-2).ToString('o'); type = 'service.end'; svc = 'app'; status = 'ok'; bytes = 10GB } | ConvertTo-Json -Compress)
        Mock -ModuleName BackupCommon Get-FreeSpaceBytes { 15GB }
        Get-RunLines -Config (New-Cfg -Svc '{ "headroomRatio": 1.0, "headroomGiB": 0 }') -Paths $paths | Out-Null
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.skip' }).Count | Should -Be 0
    }

    It 'does not check a service with no recorded size' {
        Mock -ModuleName BackupCommon Get-FreeSpaceBytes { 0 }
        Get-RunLines -Config (New-Cfg) -Paths $paths | Out-Null
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.skip' }).Count | Should -Be 0
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeTrue
    }
}

Describe 'insufficient-space in status and report' {
    It 'prints the formula from an event that carries its terms' {
        $ev = Join-Path $Work 'sh-status.jsonl'
        $iso = { param($m) (Get-Date '2026-11-22T19:00:00').AddMinutes($m).ToString('o') }
        foreach ($e in @(
                @{ ts = (& $iso 0); type = 'run.begin'; runId = 'r1' }
                @{ ts = (& $iso 1); type = 'service.skip'; runId = 'r1'; svc = 'paperless'; reason = 'insufficient-space'
                    needBytes = [long](800GB * 1.2 + 10GB); freeBytes = 900GB; lastBytes = 800GB; ratio = 1.2; marginBytes = 10GB }
                @{ ts = (& $iso 2); type = 'run.end'; runId = 'r1'; summary = @{ ok = 0; failed = 0; planned = 1 } })) {
            Add-Content -LiteralPath $ev -Value ($e | ConvertTo-Json -Compress)
        }
        $events = @(Get-BackupEvents -EventsPath $ev)
        $run = @(Get-RunStates -Events $events -LockPath (Join-Path $Work 'sh-none.lock'))[-1]
        $text = (Format-RunDetail -Detail (Get-RunDetail -Events $events -Run $run)) -join "`n"
        $text | Should -Match ([regex]::Escape('insufficient space in the spool (need 970.0 GB = 800.0 GB x 1.2 + 10.0 GB, free 900.0 GB)'))
    }
}
